# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Cost+throughput-aware load-balanced broadcast routing.

    Three candidate trees are computed once from src:
      1. classic Dijkstra on known edge costs,
      2. Dijkstra treating cost=None (free) edges as cost 0,
      3. Dijkstra on capacity-aware weights (cost/throughput) to find
         fast parallel routes through different networks.
    Partition 0 of each destination always rides the genuinely cheapest
    route (baseline-safe); remaining partitions are load-balanced onto
    the throughput-aware parallel route so transfers overlap across
    multi-network topologies instead of stacking on one trunk. Unreachable
    destinations (and src itself) get empty paths so nothing is
    transferred for them, keeping every configuration successful.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    # Weighted copy: missing costs become free so those links become usable
    g_free = G.copy()
    for u, v, d in g_free.edges(data=True):
        if d.get("cost") is None:
            d["cost"] = 0
    g_free.remove_edges_from(list(g_free.in_edges(src))
                              + list(nx.selfloop_edges(g_free)))

    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    # Default: empty paths for every dst/partition (nothing to transfer)
    for dst in dsts:
        for p in range(num_partitions):
            bc_topology.set_dst_partition_paths(dst, p, [])

    if src not in h:
        return bc_topology

    # Weighted copy for throughput-aware routing (capacity-aware weights)
    g_tput = h.copy()
    for u, v, d in g_tput.edges(data=True):
        t = d.get("throughput") or 0.0
        c = d.get("cost")
        c = c if c is not None else 0.0
        # Weight balancing $/GB against link capacity: cheap+fast edges win
        d["wt"] = c / max(t, 1e-9) if t > 0 else c

    # Candidate 1: classic min-cost tree on known costs
    try:
        dist, paths = nx.single_source_dijkstra(h, src, weight="cost")
    except Exception:
        dist, paths = {}, {}
    # Candidate 2: tree that may route through free edges
    try:
        dist_f, paths_f = nx.single_source_dijkstra(g_free, src, weight="cost")
    except Exception:
        dist_f, paths_f = {}, {}
    # Candidate 3: throughput-aware tree (spreads load onto fast networks)
    try:
        _, paths_t = nx.single_source_dijkstra(g_tput, src, weight="wt")
    except Exception:
        paths_t = {}

    def real_cost(path):
        c = 0.0
        for i in range(len(path) - 1):
            edge_cost = G[path[i]][path[i + 1]].get("cost")
            c += edge_cost if edge_cost is not None else 0.0
        return c

    for dst in dict.fromkeys(dsts):  # dedupe, preserve order
        if dst == src:
            continue
        # Collect low-cost candidate routes
        cand = []
        for tree in (paths, paths_f):
            if dst in tree and len(tree[dst]) > 1:
                cand.append(tree[dst])
        if not cand:
            continue  # unreachable or src itself: keep empty paths
        # Baseline-cheapest route: used by partition 0 (never worse than Dijkstra)
        cheap = min(cand, key=real_cost)
        # Parallel route: throughput-aware (disjoint network when available)
        fast = paths_t.get(dst) if dst in paths_t and len(paths_t[dst]) > 1 else None

        def edge_list(path):
            return [[path[i], path[i + 1], G[path[i]][path[i + 1]]]
                    for i in range(len(path) - 1)]

        cheap_e = edge_list(cheap)
        # Partition 0 rides the globally cheapest route; later partitions are
        # load-balanced onto the parallel throughput-aware route so transfers
        # overlap across networks instead of stacking on one trunk.
        share_fast = num_partitions > 1 and fast is not None and fast != cheap
        for p in range(num_partitions):
            if p == 0 or not share_fast:
                bc_topology.set_dst_partition_paths(dst, p, cheap_e)
            else:
                bc_topology.set_dst_partition_paths(dst, p, edge_list(fast))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


